/**
 * Wrap seed/dev-seed.sql as a TypeScript module.
 *
 * demo.ts needs the seed text at runtime in the deployed Function, and every
 * toolchain that touches this repo -- esbuild, tsx, vitest -- would otherwise
 * need its own ".sql means text" loader. A generated .ts module needs none of
 * them, so the special-casing disappears rather than being replicated.
 *
 * Regenerated by `npm run seed:generate`; the .sql file stays the source of
 * truth and is what `db:reset` applies.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const sql = readFileSync(fileURLToPath(new URL('../seed/dev-seed.sql', import.meta.url)), 'utf8');
const out = fileURLToPath(new URL('../seed/dev-seed.ts', import.meta.url));

writeFileSync(
  out,
  `/* GENERATED by scripts/seed-to-module.mjs -- edit seed/dev-seed.sql instead. */\n` +
    `export default ${JSON.stringify(sql)};\n`,
  'utf8',
);

console.log(`seed/dev-seed.ts written (${(sql.length / 1024).toFixed(0)} KB of SQL)`);
